 class EnvVarCheck
 {
     // Returns true if the variable exists in the environment block,
     // even when its value is the empty string.
     static bool IsEnvironmentVariableDefined(string variable)
     {
         return Environment.GetEnvironmentVariables().Contains(variable);
     }

     void CheckFlag()
     {
         // On Linux, set via: export MY_FLAG=""
         var val = Environment.GetEnvironmentVariable("MY_FLAG");
         // .NET 9 breaking change: on Linux, empty env vars now return ""
         // instead of null. Use explicit presence check to distinguish
         // "not set" from "set to empty".
